let results = [];

// 1. Забираємо відповідь від Gemini (перевіряємо обидві можливі назви ноди)
let aiItems = [];
try { aiItems = $('Basic LLM Chain1').all(); } catch (e) {
  try { aiItems = $('Basic LLM Chain').all(); } catch (e2) {}
}

// 2. Забираємо елементи з Photoroom (HTTP Request)
const photoItems = $('HTTP Request').all();
const count = Math.max(photoItems.length, 1);

for (let i = 0; i < count; i++) {
  const aiItem = aiItems[i] || aiItems[0] || {};
  const rawAiText = (
    (aiItem.json && (aiItem.json.text || aiItem.json.output || aiItem.json.response)) || ''
  ).replace(/\*\*/g, '').trim();

  const extractField = (label) => {
    const regex = new RegExp(label + ':\\s*(.+)', 'i');
    const match = rawAiText.match(regex);
    return match ? match[1].trim() : '';
  };

  const titleUa = extractField('TITLE_UA') || (rawAiText.split('\n')[0] || `Позиція каталогу #${i + 1}`);
  const titleEn = extractField('TITLE_EN') || `Catalog Item SKU-${1001 + i}`;
  const description = extractField('DESCRIPTION') || rawAiText || 'Помилка отримання тексту від Gemini';
  const specs = extractField('SPECS') || 'Визначено візуально за фото';
  const keywords = extractField('KEYWORDS') || titleUa.toLowerCase();

  // 3. Витягуємо справжній файл Photoroom (навіть якщо він схований у filesystem-v2)
  let imageBase64 = null;
  try {
    const targetItem = photoItems[i] || photoItems[0];
    if (targetItem && targetItem.binary) {
      const binKey = targetItem.binary.data ? 'data' : Object.keys(targetItem.binary)[0];
      const binObj = targetItem.binary[binKey];
      if (binObj) {
        const mime = binObj.mimeType || 'image/png';
        if (binObj.data && binObj.data !== 'filesystem-v2' && !binObj.data.includes('filesystem')) {
          imageBase64 = binObj.data.startsWith('data:') ? binObj.data : `data:${mime};base64,${binObj.data}`;
        } else {
          // Читаємо бінарний буфер з диска n8n через вбудований хелпер
          const buffer = await this.helpers.getBinaryDataBuffer(i, binKey);
          imageBase64 = `data:${mime};base64,${buffer.toString('base64')}`;
        }
      }
    }
  } catch (err) {
    // Якщо прямий буфер недоступний з чужої ноди, беремо з поточного входу
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
      imageBase64 = `data:image/png;base64,${buffer.toString('base64')}`;
    } catch (e2) {}
  }

  results.push({
    json: {
      id: i + 1,
      sku: `SKU-${1001 + i}`,
      title_ua: titleUa,
      title_en: titleEn,
      description: description,
      characteristics: specs,
      keywords: keywords,
      image_base64: imageBase64,
      status: "success"
    }
  });
}

return results;
